import{_ as i,l as o,o as e,c as n,v as r,p as s,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"模型风险清单","description":"","frontmatter":{"title":"模型风险清单","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/model-risk-inventory.md","filePath":"quant/model-risk-inventory.md","lastUpdated":1789023840000}'),E={name:"quant/model-risk-inventory.md"};function m(c,a,u,A,B,_){const l=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="模型风险清单" tabindex="-1">模型风险清单 <a class="header-anchor" href="#模型风险清单" aria-label="Permalink to &quot;模型风险清单&quot;">​</a></h1><div class="epigraph"><p>模型风险不是「某个公式算错一位」。它是模型被用在其假设已经失效的决策上，而机构还没有一张表说清：哪些假设、由谁负责、失效时改用什么。</p><footer>—— 据 Board of Governors of the Federal Reserve System, SR 11-7, Supervisory Guidance on Model Risk Management, 2011</footer></div><p><a href="/quant/liquidity-spiral-risk">流动性螺旋</a>给出了一种具体的、多模型同时失效的机制。本课的缺口是工程与治理：把定价、风险、执行、估值用到的模型收成<strong>清单</strong>，使失效可被点名。SR 11-7 把模型风险定义成错误的模型或正确模型的错误使用，要求开发、验证、使用分开。量化研究里的过拟合、体制切换、相关崩溃，都是清单上的条目，而不是互不往来的论文主题。后课压力与反向压力是清单驱动的测试，不是每年一次的情景故事会。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一个交易台同时依赖：信号模型、冲击模型、风险 \\(\\Sigma\\)、期权曲面、债券曲线、公司行为、另类数据映射。每一块都有文档里没写的假设：平稳性、外生流动性、高斯尾、点-in-time 可用、对手会按历史填成率成交。螺旋来时，假设成组破裂，但事故复盘却只抓「波动估低了」。缺口是一张表：模型名称、用途（定价 / 限额 / 执行 / 估值）、关键假设、输入数据契约、验证日期、已知失效模式、替代方案。没有这张表，就无法做下一课的反向压力——你不知道要逆推哪一个模型。</p><p>SR 11-7 的精神适用于并非银行持牌的研究团队：任何决定仓位或限额的计算都是模型。Excel 不是豁免。清单的粒度要到「可被关掉或替换」，不要到「整个量化部」。</p><h3 id="错误的模型-vs-错误的使用" tabindex="-1">错误的模型 vs 错误的使用 <a class="header-anchor" href="#错误的模型-vs-错误的使用" aria-label="Permalink to &quot;错误的模型 vs 错误的使用&quot;">​</a></h3><p>错误的模型：识别失败、样本外崩溃、数值 bug。错误的使用：把做市实现价差拿去成本化月频因子；把平静期 lambda 送进螺旋第二圈；把修订后的宏观序列当实时。后一类在量化事故里更常见，因为「模型回测还行」。清单必须把<strong>用途</strong>写成字段：同一套 \\(\\Sigma\\)，用于解释归因可以，用于设定杠杆则需要压力版本。用途变了，验证要重做。</p><p><span class="marginnote">过拟合是模型风险的一种，见过拟合作为风险课。清单上应写：尝试次数、是否 deflated Sharpe、是否与生产共用样本。不要只写「用了交叉验证」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>盘点：从生产信号、风控闸门、盘中估值、保证金预测、执行算法各自往回追依赖的模型与数据。每一条记录：所有者、最后验证、输入是否点-in-time、对流动性/相关/填成的假设、与哪些模型共同失效（螺旋是典型簇）。验证独立于开发：至少换样本段、换冲击函数、换相关估计。SR 11-7 要求的是持续性，不是上线前一次。</p><p>失效模式预填：体制切换、相关崩溃、流动性螺旋、数据修订、公司行为漏处理、模拟器冲击为零、时钟错配。每一条指向已有课程，避免清单变成空话。替代方案必须可执行：例如「关掉该信号、杠杆上限切到压力 \\(\\Sigma\\)、执行改拍卖、债券改按变现时间限额」。不能写「届时开会讨论」。</p><h3 id="清单是限额系统的输入" tabindex="-1">清单是限额系统的输入 <a class="header-anchor" href="#清单是限额系统的输入" aria-label="Permalink to &quot;清单是限额系统的输入&quot;">​</a></h3><p>监控课已经把 PnL、敞口、拒单分开。模型风险清单决定：哪一个敞口数字来自哪一个模型，拒单是否因为模型输入迟到。把清单 ID 打进订单与限额，事故时才能回答「坏的是曲面还是冲击」。这是治理，不是更多的希腊字母。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>模型风险进入损益的路径是决策。错误估值导致错误杠杆；错误冲击导致错误容量；错误相关导致错误分散。螺旋把多条路径同时打开。清单不能消灭风险，但能把「我们不知道自己依赖什么」变成「我们知道哪三条假设刚被代理指标证伪」。验证的机制是独立挑战：开发者的损失函数是样本内表现，验证者的损失函数是假设清单是否完整。激励不分开，验证会变成表演。</p><p><span class="marginnote">不要把 <a href="/quant/kyle-model">Kyle</a> 或 <a href="/quant/roll-model">Roll</a> 写进清单当「已验证的真理」。写进去的应是你校准的经验 lambda、你用的 Roll 窗口、以及它们在停板日失效。理论论文是出处，不是生产模型。</span></p>',17)),(e(),s(h,null,{default:t(()=>[p(l,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TB%0A%20%20INV%5B%22%E6%A8%A1%E5%9E%8B%E6%B8%85%E5%8D%95%22%5D%20--%3E%20U%5B%22%E7%94%A8%E9%80%94%EF%BC%9A%E5%AE%9A%E4%BB%B7%20%2F%20%E9%99%90%E9%A2%9D%20%2F%20%E6%89%A7%E8%A1%8C%22%5D%0A%20%20INV%20--%3E%20A%5B%22%E5%85%B3%E9%94%AE%E5%81%87%E8%AE%BE%22%5D%0A%20%20INV%20--%3E%20F%5B%22%E5%B7%B2%E7%9F%A5%E5%A4%B1%E6%95%88%E6%A8%A1%E5%BC%8F%22%5D%0A%20%20F%20--%3E%20ALT%5B%22%E5%8F%AF%E6%89%A7%E8%A1%8C%E6%9B%BF%E4%BB%A3%22%5D%0A%20%20A%20--%3E%20ST%5B%22%E5%8E%8B%E5%8A%9B%20%2F%20%E5%8F%8D%E5%90%91%E5%8E%8B%E5%8A%9B%22%5D%0A%20%20ALT%20--%3E%20ST%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h3 id="供应商模型也要进清单" tabindex="-1">供应商模型也要进清单 <a class="header-anchor" href="#供应商模型也要进清单" aria-label="Permalink to &quot;供应商模型也要进清单&quot;">​</a></h3><p>风险软件、复权算法、另类面板都是模型。责任不能因外包而消失。清单上应有供应商名称、版本、你无法验证的假设，以及关掉该输入时的替代。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>监管文本针对银行模型体系，研究基金可以按比例裁剪，但不能裁掉「用途」和「假设」两列。供应商模型（风险软件、数据复权）也要进清单，责任不能外包消失。下一课用清单上的假设去设计压力与反向压力：先问什么会让我们破产，再看哪个模型必须先坏。</p><p><span class="marginnote">Excel 与研究笔记本里决定仓位的计算，用途与生产信号相同，不能因为没进代码库就豁免验证。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>模型风险是错误模型或错误用途；清单把假设、用途、失效与替代写成可关闭的单元。</li><li>螺旋是多模型同时失效的簇，应在清单里预链。</li><li>同一套参数换用途必须重新验证。</li><li>替代方案必须可执行，不能停在「开会」。</li><li>理论模型是出处；生产条目是校准后的估计器与数据契约。</li><li>出处：Federal Reserve SR 11-7, 2011；过拟合与体制切换见本课序前几课；流动性螺旋见 Brunnermeier–Pedersen。</li></ul>',7))])}const S=i(E,[["render",m]]);export{q as __pageData,S as default};
